# Task 1: Import requests and JSONDecodeError
import requests
from requests.exceptions import JSONDecodeError

# Setup (DO NOT MODIFY)
base_url = 'https://jsonplaceholder.typicode.com'

# --- Task 2-3: Fetch pending tasks (GET) ---
print("\n--- Pending Tasks for User 5 ---")

# Parameters for filtering (already set up)
get_params = {
    'userId': 5,
    'completed': 'false'
}

# Task 2: Make the GET request
get_response = requests.get(f'{base_url}/todos', params=get_params)

# Task 3: Process the GET response with try/except
try:
    tasks = get_response.json()

    if get_response.status_code == 200:
        for task in tasks:
            print(f"[ ] {task['title']}")
    else:
        print(f"Failed to fetch tasks. Status code: {get_response.status_code}")

except JSONDecodeError:
    print("Error: Invalid JSON response from server")


# --- Task 4-5: Create a new task (POST) ---
print("\n--- Creating New Task ---")

# New task data (already set up)
new_task = {
    'userId': 5,
    'title': 'Complete API Project',
    'completed': True
}

# Task 4: Make the POST request
post_response = requests.post(f'{base_url}/todos', json=new_task)

# Task 5: Process the POST response with try/except
try:
    created_task = post_response.json()

    if post_response.status_code == 201:
        print(f"Successfully created task with ID: {created_task['id']}")
    else:
        print(f"Failed to create task. Status code: {post_response.status_code}")

except JSONDecodeError:
    print("Error: Invalid JSON response from server")

